files.content:
body {
  display: flex;
  min-height: 100vh;
  background-color: rgb(169 0 169);
}

.round {
  display: flex;
  margin: auto;
  width: 250px;
  height: 250px;
  border-radius: 50%;
  background-color: #000;
}

.round .round {
  width: 200px;
  height: 200px;
  background-color: navy;
}

.round .round .round {
  width: 150px;
  height: 150px;
  background-color: white;
}

.round .round .round .round {
  width: 100px;
  height: 100px;
  background-color: green;
}

.round .round .round .round .round {
  width: 50px;
  height: 50px;
  background-color: red;
}
